import {currentLanguage,label,ui} from './language.mjs';

const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function guideCopy(guide){
 const filipino=currentLanguage()==='fil'&&Boolean(guide.titleFil&&guide.contentFil);
 return {title:filipino?guide.titleFil:guide.title,summary:filipino?(guide.summaryFil||''):guide.summary,content:filipino?guide.contentFil:guide.content,language:filipino?'fil':'en',fallback:currentLanguage()==='fil'&&!filipino};
}
const updated=guide=>guide.updatedOn?ui`<span>${label('Updated {date}',{date:{date:guide.updatedOn,format:'short'}})}</span>`:'';
export function clinicGuideResults(guides,{isStaff=false,query='',filter='All'}={}){
 const search=query.trim().toLocaleLowerCase();
 const records=guides.filter(g=>(isStaff||g.status==='Published')&&(filter==='All'||g.status===filter)&&(!search||[g.title,g.titleFil,g.summary,g.summaryFil,g.content,g.contentFil,g.category,g.sourceName].some(value=>String(value??'').toLocaleLowerCase().includes(search)))).sort((a,b)=>(b.updatedOn??'').localeCompare(a.updatedOn??'')||a.title.localeCompare(b.title));
 if(!records.length)return ui`<div class="clinic-guide-empty"><h3>${label(search||filter!=='All'?'No matching clinic guides.':isStaff?'Share what matters in your barangay.':'Your clinic has not shared any guides yet.')}</h3><p>${label(search||filter!=='All'?'Try another search or status.':isStaff?'Add local instructions, clinic updates or an article for your community.':'Published clinic articles will appear here after sync. The general guides below are ready to read.')}</p></div>`;
 return ui`<div class="clinic-guide-grid">${records.map(guide=>{const copy=guideCopy(guide);return ui`<article class="clinic-guide-card" data-guide-card="${escape(guide.id)}"><div class="clinic-guide-meta"><span class="eyebrow">${label(guide.category)}</span>${isStaff?ui`<span class="badge ${guide.status==='Published'?'':guide.status==='Draft'?'warning':'muted'}">${label(guide.status)}</span>`:''}</div><h3 lang="${copy.language}">${escape(copy.title)}</h3><p class="clinic-guide-summary" lang="${copy.language}">${escape(copy.summary||copy.content.slice(0,180))}${!copy.summary&&copy.content.length>180?'…':''}</p>${copy.fallback?ui`<p class="data-note">English version · Filipino translation not yet added.</p>`:''}<div class="clinic-guide-source">${guide.sourceName?ui`<span>${escape(guide.sourceName)}</span>`:''}${updated(guide)}</div><div class="button-stack"><button class="button secondary" data-read-guide="${escape(guide.id)}">Read guide ↗</button>${isStaff?ui`<button class="row-button" data-edit="guides" data-id="${escape(guide.id)}">Edit guide</button><button class="row-button danger-action" data-delete="guides" data-id="${escape(guide.id)}">Delete guide</button>`:''}</div></article>`;}).join('')}</div>`;
}
export function clinicGuideReader(guide){
 const copy=guideCopy(guide);
 let url='';try{const parsed=new URL(guide.resourceUrl);if(parsed.protocol==='https:'&&!parsed.username&&!parsed.password)url=parsed.href;}catch{}
 return ui`<article class="clinic-guide-reader"><p class="eyebrow">${label(guide.category)}</p><h3 lang="${copy.language}">${escape(copy.title)}</h3>${guide.status&&guide.status!=='Published'?ui`<p class="notice warning">${label(guide.status==='Draft'?'Draft · Only staff can see this guide.':'Archived · Hidden from patient accounts after sync.')}</p>`:''}${copy.fallback?ui`<p class="data-note">English version · Filipino translation not yet added.</p>`:''}${copy.summary?ui`<p class="clinic-guide-intro" lang="${copy.language}">${escape(copy.summary)}</p>`:''}<div class="clinic-guide-article" lang="${copy.language}">${escape(copy.content)}</div><footer>${guide.sourceName?ui`<p><strong>Source / clinic</strong><br>${escape(guide.sourceName)}</p>`:''}${updated(guide)}${url?ui`<p><a class="external-resource" href="${escape(url)}" target="_blank" rel="noopener noreferrer">Open linked material ↗</a></p><p class="data-note">External articles, PDFs and videos need an internet connection.</p>`:''}</footer></article>`;
}
